parameters.jsCode:
// ---------------------------------------------------------------
// Idempotency resolution — two rules that keep a bank out of trouble:
//  1. The key is derived from the BUSINESS EVENT, never from the attempt.
//     Same person + same product = same application, however many times
//     the client retries.
//  2. Same key + DIFFERENT payload must 409 (the database answers that).
//     Silently returning the original would hide a client bug, or an
//     attempt to swap the applicant behind a key that is already known.
// Malformed input is a 400 here; no application is created for it.
// ---------------------------------------------------------------
const crypto = require('crypto');   // needs NODE_FUNCTION_ALLOW_BUILTIN=crypto

const body    = $input.first().json.body ?? {};
const headers = $input.first().json.headers ?? {};

const customerRef = String(body.customer_external_ref ?? '').trim();
const product     = String(body.product_code ?? '').trim();
const a           = body.applicant;

const problems = [];
if (!customerRef) problems.push('customer_external_ref is required');
if (!product)     problems.push('product_code is required');
if (!a || typeof a !== 'object' || Array.isArray(a)) problems.push('applicant must be an object');
else {
  for (const f of ['given_name', 'family_name', 'date_of_birth', 'country'])
    if (!String(a[f] ?? '').trim()) problems.push(`applicant.${f} is required`);
  if (a.date_of_birth && !/^\d{4}-\d{2}-\d{2}$/.test(a.date_of_birth)) problems.push('applicant.date_of_birth must be YYYY-MM-DD');
  if (a.country && !/^[A-Z]{2}$/.test(a.country)) problems.push('applicant.country must be ISO 3166-1 alpha-2');
}
if (problems.length) return [{ json: { _halt: true, status: 400, error: 'validation_failed', problems } }];

// Client MAY supply a key. If it does not, derive a deterministic one —
// so a client that forgets the header still cannot create duplicates.
const clientKey = headers['idempotency-key'];
const idempotencyKey = clientKey
  ? String(clientKey)
  : crypto.createHash('sha256').update(`${customerRef}:${product}`).digest('hex');

// Fingerprint the fields that define the request, with keys sorted at EVERY
// depth. (JSON.stringify's replacer-array would also filter nested keys and
// silently fingerprint the applicant as {} — the 409 would never fire.)
const canonical = (v) => Array.isArray(v) ? `[${v.map(canonical).join(',')}]`
  : v && typeof v === 'object'
    ? `{${Object.keys(v).sort().map(k => `${JSON.stringify(k)}:${canonical(v[k])}`).join(',')}}`
    : JSON.stringify(v);

const requestFingerprint = crypto.createHash('sha256')
  .update(canonical({ customer_external_ref: customerRef, product_code: product, applicant: a }))
  .digest('hex');

return [{ json: {
  _halt: false,
  customer_external_ref: customerRef,
  product_code: product,
  applicant: a,
  idempotency_key: idempotencyKey,
  request_fingerprint: requestFingerprint
} }];

// Business eligibility, after the application exists — so a decline is an
// audited state (rejected, with a reason), not a lost HTTP error.
// The country list is illustrative.
const app = $('PG: submit application').first().json;
const a   = $('Resolve idempotency').first().json.applicant;

const SUPPORTED = ['AT','BE','DE','EE','ES','FI','FR','IE','IT','LT','LV','NL','PL','PT','SE'];
const dob  = new Date(a.date_of_birth + 'T00:00:00Z');
const now  = new Date();
let age    = now.getUTCFullYear() - dob.getUTCFullYear();
if (now.getUTCMonth() < dob.getUTCMonth() ||
   (now.getUTCMonth() === dob.getUTCMonth() && now.getUTCDate() < dob.getUTCDate())) age--;

const reason = Number.isNaN(age) ? 'invalid_date_of_birth'
             : age < 18           ? 'under_18'
             : !SUPPORTED.includes(a.country) ? 'country_not_supported'
             : null;

return [{ json: {
  application_id: app.application_id,
  next: reason ? 'rejected' : 'screening',
  reason: reason ?? 'eligible',
  tkey: `${app.application_id}:eligibility`
} }];

