-- The workflow never UPDATEs state. It asks the database for a legal
-- transition, and the database is the one that says no.
select $1::uuid as application_id, t.*
  from app.transition_application(
         $1::uuid,                    -- application
         null,                        -- expected_from: the table decides
         $2::app.application_state,   -- to
         'system', $3, $4,            -- actor, actor_ref (execution), reason
         $5                           -- transition idempotency key
       ) t;

parameters.jsCode:
// A screening HIT is never auto-rejected and never auto-approved — it goes
// to a human, because that is a regulatory decision, not a workflow branch.
// Screening being unavailable is not a rejection either.
const res   = $input.first().json;
const appId = $('PG: transition (eligibility)').first().json.application_id;

const ok   = res.statusCode >= 200 && res.statusCode < 300;
const hits = ok ? (res.body?.matches ?? []) : null;

const next   = !ok ? 'kyc_review' : hits.length > 0 ? 'kyc_review' : 'kyc_pending';
const reason = !ok ? 'screening_unavailable' : hits.length > 0 ? 'sanctions_hit' : 'screening_clear';

return [{ json: { application_id: appId, next, reason, tkey: `${appId}:screening` } }];

