parameters.jsCode:
// The whole point of this node: a timeout is NOT a decision.
//
// 2xx  → stays kyc_pending; the decision arrives later as a signed callback
// 4xx  → the provider refused the request itself → a human looks (kyc_review)
// 5xx / timeout / no response → kyc_unknown. We do not know whether the
//        provider created the check. Resubmitting blind could double-charge
//        the KYC vendor and, worse, create two identities.
const out = [];
$input.all().forEach((item, i) => {
  const res  = item.json;
  const app  = $('PG: transition (screening)').itemMatching(i).json;
  const code = res.statusCode ?? 0;
  const base = { application_id: app.application_id };
  if (code >= 200 && code < 300) {
    out.push({ json: { ...base, next: 'kyc_pending', provider_ref: res.body?.id ?? null }, pairedItem: i });
  } else if (code >= 400 && code < 500) {
    out.push({ json: { ...base, next: 'kyc_review', reason: `provider_rejected_request_${code}`,
                        tkey: `${app.application_id}:submit:v${app.version}` }, pairedItem: i });
  } else {
    out.push({ json: { ...base, next: 'kyc_unknown',
                        reason: code === 0 ? 'timeout_no_response' : `provider_5xx_${code}`,
                        tkey: `${app.application_id}:submit:v${app.version}` }, pairedItem: i });
  }
});
return out;

