// One place that turns what happened into an HTTP answer. Internal states
// never leave the bank: telling an applicant "kyc_review" after a sanctions
// hit is tipping-off. The client sees a coarse public status.
const PUBLIC = {
  draft: 'received', submitted: 'received',
  screening: 'in_progress', kyc_pending: 'in_progress', kyc_unknown: 'in_progress', kyc_review: 'in_progress',
  approved: 'approved', account_opened: 'approved', rejected: 'declined', expired: 'expired',
};
const resolved = $('Resolve idempotency').first().json;
if (resolved._halt) {
  return [{ json: { http_status: resolved.status,
                    response: { error: resolved.error, problems: resolved.problems } } }];
}

const sub = $('PG: submit application').first().json;
const latest = $input.first().json;           // output of the last step that ran

switch (sub.outcome) {
  case 'key_conflict':
    return [{ json: { http_status: 409, response: {
      error: 'idempotency_key_reuse_with_different_payload', application_id: sub.application_id } } }];
  case 'already_open':
    return [{ json: { http_status: 409, response: {
      error: 'application_already_open', application_id: sub.application_id } } }];
  case 'replay':
    // Return current state; never restart the process.
    return [{ json: { http_status: 200, response: {
      application_id: sub.application_id, status: PUBLIC[sub.state] } } }];
  default:
    return [{ json: { http_status: 201, response: {
      application_id: sub.application_id, status: PUBLIC[latest.state ?? sub.state] } } }];
}

// ---------------------------------------------------------------
// Inbound webhook hardening. Four separate concerns, all mandatory:
//
//  1. Verify HMAC over the RAW bytes, BEFORE parsing. With rawBody on, n8n
//     keeps the exact bytes as binary 'data'; json.body is already a parse.
//     Re-serialising a parse changes bytes and the signature never matches
//     — and "fixing" that by trusting the parse means no signature check.
//  2. Constant-time compare. A fast-fail === leaks the signature by timing.
//  3. Timestamp tolerance. Without it a captured payload replays forever.
//  4. Only THEN look at the contents.
// ---------------------------------------------------------------
const crypto = require('crypto');   // needs NODE_FUNCTION_ALLOW_BUILTIN=crypto

const item    = $input.first();
const headers = item.json.headers ?? {};
const reject  = (reason) => [{ json: { _ok: false, status: 401, reason } }];

const secret    = $env.KYC_WEBHOOK_SECRET;
const signature = String(headers['x-provider-signature'] ?? '');
const timestamp = String(headers['x-provider-timestamp'] ?? '');

if (!secret)                  return reject('server_misconfigured_no_secret');
if (!signature || !timestamp) return reject('missing_signature_headers');
if (!item.binary?.data)       return reject('raw_body_unavailable');

// 3. Replay window — five minutes either side of now.
const skew = Math.abs(Date.now() / 1000 - Number(timestamp));
if (!Number.isFinite(skew) || skew > 300) return reject('timestamp_outside_tolerance');

// 1. Sign exactly what was sent: timestamp + '.' + raw bytes.
const raw      = await this.helpers.getBinaryDataBuffer(0, 'data');
const expected = crypto.createHmac('sha256', secret)
                       .update(Buffer.concat([Buffer.from(`${timestamp}.`), raw]))
                       .digest('hex');

// 2. Constant-time. Lengths must match first or timingSafeEqual throws.
const a = Buffer.from(expected, 'utf8');
const b = Buffer.from(signature, 'utf8');
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return reject('bad_signature');

// 4. Trusted from here on.
let payload;
try { payload = JSON.parse(raw.toString('utf8')); }
catch { return reject('unparseable_body'); }
if (!payload.event_id) return reject('incomplete_event');

// Only an actual decision moves state. Lifecycle events (check.started,
// document.uploaded…) are recorded and acknowledged — a provider sends many.
const decisionMap = { CLEAR: 'approved', DECLINE: 'rejected', REFER: 'kyc_review' };

return [{ json: {
  _ok: true,
  event_id:       String(payload.event_id),
  provider_ref:   String(payload.check_id ?? ''),
  client_reference: String(payload.client_reference ?? ''),
  sequence_no:    payload.sequence ?? null,
  event_type:     String(payload.event_type ?? payload.decision ?? ''),
  next:           decisionMap[payload.decision] ?? null,
  reason:         `provider_${payload.decision ?? payload.event_type ?? 'event'}`,
  payload
} }];

