-- and the provider is asked directly. The BPMN boundary timer, in SQL.
select * from app.flag_overdue_pending(interval '6 hours');

parameters.jsCode:
// QUERY FIRST, resubmit second — and only when we are certain the provider
// never received it. Blind resubmission is how one applicant becomes two
// identities. Handles every claimed application, not just the first.
// Transition keys carry the state version: the same provider answer seen in a
// later trip through kyc_unknown is a new transition, not a "duplicate".
const MAX_ATTEMPTS = 8;
const decisionMap = { CLEAR: 'approved', DECLINE: 'rejected', REFER: 'kyc_review' };
const out = [];

$input.all().forEach((item, i) => {
  const res   = item.json;
  const app   = $('PG: claim UNKNOWN').itemMatching(i).json;
  const code  = res.statusCode ?? 0;
  const check = res.body?.data?.[0];
  const emit  = (next, reason, tkey) =>
    out.push({ json: { application_id: app.id, next, reason, tkey,
                       kyc_attempts: app.kyc_attempts }, pairedItem: i });

  if (code === 200 && check && check.status === 'complete') {
    // Found, and finished → apply the real decision.
    emit(decisionMap[check.result] ?? 'kyc_review', `reconciled_${check.result}`, `recon:${app.id}:v${app.version}`);
  } else if (app.kyc_attempts >= MAX_ATTEMPTS) {
    // Budget spent — still processing, never received, or unreachable — so a
    // human owns it now. Note: kyc_review, never rejected.
    emit('kyc_review', 'reconcile_exhausted', `giveup:${app.id}:v${app.version}`);
  } else if (code === 200 && check) {
    // Found, still running → leave it; back-off is already re-armed.
  } else if (code === 200 && !check) {
    // Definitively never received → resubmit with the SAME idempotency key.
    emit('kyc_pending', 'never_received_resubmitting_same_key', `rearm:${app.id}:v${app.version}`);
  }
  // else: provider unreachable, budget left → try again next pass.
});
return out;

